'use strict';

// MODULES //

var dtypeChar = require( '@stdlib/ndarray/base/dtype-char' );
var format = require( '@stdlib/string/format' );
var DTYPE_HIERARCHY = require( '@stdlib/math/special/scripts/dtype_hierarchy.js' );


// FUNCTIONS //

/**
* Maps dtype pairs to appropriate scalar functions.
*
* ## Note
*
* -   The function returns an array with the following structure:
*
* ```text
*             ---------------------------------------------------------------------------------
*  Array:    |     kernel       |      cFunc       |   ndarrayKernel      |     match        |
*             ---------------------------------------------------------------------------------
*                     |                |                    |                    |
*                     |                |                    |                    |
*                     V                V                    V                    V
*  Example:  '@stdlib/math/base/  'stdlib_base_sqrt'  'stdlib_ndarray_     ['float64',
*            special/sqrt'                            f_d_as_d_d'          'float64']
* ```
*
* @private
* @param {Array} iopair - input-output dtype pair
* @param {Array} iodt - array of available scalar kernel dtypes
* @param {Object} scalarKernels - scalar kernels object
* @returns {Array} mapping result
*
* @example
* var iopair = [ 'float32', 'float64' ];
* var iodt = [
*     [ 'float32', 'float32' ],
*     [ 'float64', 'float64' ]
* ];
* var scalarKernels = {
*     'float32': '@stdlib/math/base/special/sqrtf',
*     'float64': '@stdlib/math/base/special/sqrt'
* };
*
* var result = mapToScalarKernel( iopair, iodt, scalarKernels );
* // returns [ '@stdlib/math/base/special/sqrt', 'stdlib_base_sqrt', 'stdlib_ndarray_f_d_as_d_d', [ 'float64', 'float64' ] ]
*/
function mapToScalarKernel( iopair, iodt, scalarKernels ) {
	var ndarrayKernel;
	var precision1;
	var precision2;
	var matchChar1;
	var matchChar2;
	var outputChar;
	var cFuncName;
	var inputChar;
	var kernel;
	var match;
	var dtype;
	var i;

	inputChar = dtypeChar( iopair[ 0 ] );
	outputChar = dtypeChar( iopair[ 1 ] );

	// For generic input, always use highest precision kernel
	if ( iopair[ 0 ] === 'generic' ) {
		kernel = scalarKernels.float64 || scalarKernels.generic;
		cFuncName = 'stdlib_base_' + kernel.split( '/' ).pop();
		ndarrayKernel = format( 'stdlib_ndarray_%s_%s_as_d_d', inputChar, outputChar );

		return [ kernel, cFuncName, ndarrayKernel, [ 'float64', 'float64' ] ];
	}

	// Priority 1: Look for exact match in available scalar kernel dtypes:
	for ( i = 0; i < iodt.length; i++ ) {
		if ( iodt[ i ][ 0 ] === iopair[ 0 ] &&
			iodt[ i ][ 1 ] === iopair[ 1 ] ) {
			match = iodt[ i ];
			break;
		}
	}

	// Priority 2: Look for higher precision matches to break ties:
	if ( !match ) {
		/*
		* Always prefer computing at higher precision:
		* - For cases like ['float32', 'float64'], prefer computing at float64: f_d_as_d_d
		* - For cases like ['int8', 'float32'], prefer computing at float32: s_f_as_f_f
		*/

		// Get higher precision dtype using hierarchy table:
		if ( iopair[ 0 ] === iopair[ 1 ] ) {
			dtype = iopair[ 0 ];
		} else {
			precision1 = DTYPE_HIERARCHY[ iopair[ 0 ] ] || 0;
			precision2 = DTYPE_HIERARCHY[ iopair[ 1 ] ] || 0;
			dtype = ( precision2 > precision1 ) ? iopair[ 1 ] : iopair[ 0 ];
		}

		// First try: Look for (higher_precision_dtype, higher_precision_dtype)...
		for ( i = 0; i < iodt.length; i++ ) {
			if ( iodt[ i ][ 0 ] === dtype && iodt[ i ][ 1 ] === dtype ) {
				match = iodt[ i ];
				break;
			}
		}

		// Second try: Look for (input_dtype, input_dtype) if higher precision not found...
		if ( !match ) {
			for ( i = 0; i < iodt.length; i++ ) {
				if ( iodt[ i ][ 0 ] === iopair[ 0 ] &&
					iodt[ i ][ 1 ] === iopair[ 0 ] ) {
					match = iodt[ i ];
					break;
				}
			}
		}

		// Third try: Look for (output_dtype, output_dtype)...
		if ( !match ) {
			for ( i = 0; i < iodt.length; i++ ) {
				if ( iodt[ i ][ 0 ] === iopair[ 1 ] &&
					iodt[ i ][ 1 ] === iopair[ 1 ] ) {
					match = iodt[ i ];
					break;
				}
			}
		}
	}

	if ( match ) {
		// Get the scalar kernel package
		kernel = scalarKernels[ match[ 1 ] ];

		// Generate C function name
		cFuncName = 'stdlib_base_' + kernel.split( '/' ).pop();

		// Generate ndarray kernel name
		if ( match[ 0 ] === iopair[ 0 ] && match[ 1 ] === iopair[ 1 ] ) {
			// Exact match
			ndarrayKernel = format( 'stdlib_ndarray_%s_%s', inputChar, outputChar );
		} else {
			// Promotion case
			matchChar1 = dtypeChar( match[ 0 ] );
			matchChar2 = dtypeChar( match[ 1 ] );
			ndarrayKernel = format( 'stdlib_ndarray_%s_%s_as_%s_%s', inputChar, outputChar, matchChar1, matchChar2 );
		}

		return [ kernel, cFuncName, ndarrayKernel, match ];
	}

	return [];
}


// EXPORTS //

module.exports = mapToScalarKernel;
